import itertools,json
jobs='ABCDE'
slot={'A':[4,8,0,2,0],'B':[6,4,5,0,5],'C':[2,6,4,6,0],'D':[8,7,9,6,0],'E':[3,3,1,6,5]}
trans=dict(zip(jobs,[[0,1,1,3,1],[5,0,2,4,2],[3,1,0,0,3],[5,4,4,0,5],[5,0,3,4,0]]))
def nominal(p):
 return sum(slot[j][i] for i,j in enumerate(p))+sum(trans[a][jobs.index(b)] for a,b in zip(p,p[1:]))
def incident(p,s):
 pos={j:p.index(j)+1 for j in jobs}
 if s=='rain':
  if pos['E']==2 or pos['D']==5:return None
  return nominal(p)+6*max(0,pos['A']-2)
 if s=='road':
  if pos['B']==5 or pos['D']==1:return None
  return nominal(p)+8*max(0,pos['C']-3)
 if pos['D']==4 or pos['C']==1:return None
 return nominal(p)+5*max(0,pos['E']-1)
results=[]
for p in itertools.permutations(jobs):
 if p.index('A')>p.index('D'):continue
 neighbors=[(p,0)]
 for i,j in itertools.combinations(range(5),2):
  q=list(p);q[i],q[j]=q[j],q[i];q=tuple(q)
  if q.index('A')<q.index('D'):neighbors.append((q,4))
 repairs={};costs={}
 for s in ['rain','road','lift']:
  choices=[(c+fee,''.join(q)) for q,fee in neighbors if (c:=incident(q,s)) is not None]
  if not choices:break
  costs[s],repairs[s]=min(choices)
 else:results.append((nominal(p)+max(costs.values()),''.join(p),repairs,costs))
results.sort()
best=results[0]
print(json.dumps({'roster':best[1],'score':best[0],'repairs':best[2],'repair_costs':best[3],'feasible_count':len(results),'next_score':min(x[0] for x in results if x[0]>best[0])}))
print('audit', 'publications',60,'optima',sum(x[0]==best[0] for x in results),'nominal',nominal(best[1]))

