import itertools,json
jobs='ABCDE';start='ACEBD'
slot={'A':[4,8,0,2,0],'B':[6,4,5,0,5],'C':[2,6,4,6,0],'D':[8,7,9,6,0],'E':[3,3,1,6,5]}
t=dict(zip(jobs,[[0,1,1,3,1],[5,0,2,4,2],[3,1,0,0,3],[5,4,4,0,5],[5,0,3,4,0]]))
def distance(p):
 perm=[start.index(x) for x in p];seen=set();cycles=0
 for i in range(5):
  if i not in seen:
   cycles+=1;j=i
   while j not in seen:seen.add(j);j=perm[j]
 return 5-cycles
classes={i:[] for i in range(3)}
for p in itertools.permutations(jobs):
 d=distance(p)
 if d>2:continue
 pos={x:p.index(x)+1 for x in jobs}
 if pos['A']>pos['D'] or pos['E'] in (2,3) or pos['D']==5:continue
 nominal=sum(slot[x][i] for i,x in enumerate(p))+sum(t[a][jobs.index(b)] for a,b in zip(p,p[1:]))
 cost=nominal+6*max(0,pos['A']-2)+4*d+(5 if d==2 else 0)
 classes[d].append((cost,''.join(p)))
best=min(x for v in classes.values() for x in v)
print(json.dumps({'roster':best[1],'score':best[0],'best_by_swaps':{str(d):min(v)[0] if v else None for d,v in classes.items()},'feasible_by_swaps':{str(d):len(v) for d,v in classes.items()}}))
print(classes)

